"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4779],{24779:t=>{t.exports=JSON.parse('{"slug":"kurs-dollara-nizhe-83-rubley-nalogovyy-period-oktyabr-2026","locale":"zh","title":"尽管国家购汇规模为2022年以来最大，美元仍自八月以来首次跌破83卢布","description":"十月20日官方美元82.85卢布，为八月以来最低。财政部持续购汇，卢布为何在十月28日缴税前走强。","blocks":[{"id":"b001","kind":"paragraph","text":"央行将十月20日官方美元设为82.85卢布，比此前低77戈比，自八月22日以来首次低于83。欧元降至93.23，人民币12.39。十月19日场外美元最低82.56。月初相反：十月7日官方价升至85.71，2周内卢布收复跌幅。"},{"id":"b002","kind":"paragraph","text":"十月7日走弱被归因于预算规则购汇。财政部将高油价超额收入通过外汇和黄金存入福利基金。十月7日至十一月6日安排279.42十亿卢布，扣除央行售汇后国家每天净买12.1十亿，是九月6倍，为2022年一月以来最多。"},{"id":"b003","kind":"paragraph","text":"设想自由职业者收美元，须在28日前用卢布交房租。上半月持美元，到期前一周才集中卖。出口商也如此。九月税款截止十月28日，十月预算油气收入估约1万亿卢布，比九月多0.5万亿，差额很大部分来自季度额外收益税约0.36万亿。因此月下半称为缴税期。"},{"id":"b004","kind":"paragraph","text":"分析师估最大出口商十月售汇约$4十亿。当前汇率下国家月购汇约$3.2十亿，平均摊在22个交易日，所以月底供应超过需求。外部因素也助力：十月19日美元指数较近期高点低1.2%，美国又推迟对俄罗斯石油买家的关税。"},{"id":"b005","kind":"paragraph","text":"支付进口商品、旅游和跨境转账者，现在比2周前更划算。但商店提前采购，降价传导有滞后。14%关键利率也支撑卢布：贷款贵，进口需求受限，卢布存款优于外币存款。出口商和预算则不喜欢强卢布，因为每桶外汇收入换得的卢布更少。"},{"id":"b006","kind":"paragraph","text":"Zenit银行弗拉基米尔\xb7叶夫斯季费耶夫预计十月28日前美元可能到82卢布。税期后出口商所需卢布减少，售汇通常降温，而财政部继续买到十一月6日。十一月初公布新规模，取决于十月油价。油贵意味着十一月仍大量购买；油跌则同时减少国家购汇和出口商收入。"},{"id":"b007","kind":"heading","text":"美元为何在2026年十月跌破83卢布？"},{"id":"b008","kind":"paragraph","text":"石油企业须在十月28日前缴九月税，十月预算油气收入估约1万亿卢布，是九月两倍。出口商为缴税售汇，供应超过国家预算规则购买，卢布因此走强。"},{"id":"b009","kind":"heading","text":"财政部购汇时卢布为何仍升？"},{"id":"b010","kind":"paragraph","text":"国家每天等额购买约12十亿卢布，出口商出售不均，尤其集中于税期前。下半月卖方超过买方。"},{"id":"b011","kind":"heading","text":"十月28日后汇率怎样？"},{"id":"b012","kind":"paragraph","text":"税缴完后出口商所需卢布较少，售汇通常下降。财政部本轮购买持续到十一月6日，新规模取决于十月油价。"}],"sources":[{"label":"美元两个月来首次跌破83卢布","url":"https://www.kommersant.ru/doc/9042314"},{"label":"美元接近82.5卢布","url":"https://www.kommersant.ru/doc/9042203"},{"label":"央行下调官方美元汇率","url":"https://lenta.ru/news/2026/10/19/tsb-ponizil-kurs-dollara"},{"label":"央行下调美元汇率77戈比","url":"https://www.vedomosti.ru/finance/news/2026/10/19/1238342-kurs-dollara"},{"label":"2026年十月8日美元汇率","url":"https://ppt.ru/currencies/usd/08-10-2026"},{"label":"俄罗斯十月预算油气收入将达1万亿卢布","url":"https://ru.themoscowtimes.com/2026/10/15/neftegazovye-dokhody-byudzheta-rf-vyrastut-na-10-v-oktyabre-2625gg-do-1-trln-rub-raschyot-reyter-a208727"},{"label":"油价与税期支持卢布继续走强","url":"https://ru.themoscowtimes.com/2026/10/19/rubl-prodolzhaet-rost-s-uchetom-neftyanoy-i-nalogovoy-podderzhki-geopolitiki-a208952"},{"label":"财政部十月7日至十一月6日购买279.42十亿卢布外汇和黄金","url":"https://www.kommersant.ru/doc/9006327"}],"sourceBodySha256":"f25608d7c3546bcf7841b9396fc0c3e8ef4ad41fa20f369f655ea9a55be665d4"}')}}]);